// Command server runs the Sekats console: a server-rendered
// Go + htmx app that turns the DevFun Arena poker agent's own policy and
// review data into a checkable quality surface. See docs/PLAN.md.
package main

import (
	"bytes"
	"html/template"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/udingethe/sekats/internal/policy"
	"github.com/udingethe/sekats/internal/quality"
	"github.com/udingethe/sekats/internal/review"
	"github.com/udingethe/sekats/internal/store"
)

type app struct {
	tmpl         *template.Template
	dataStore    *store.Store
	surface      quality.Surface
	policyReport policy.Report
	reviewQueue  *review.Queue
}

func main() {
	dataDir := envOr("DATA_DIR", "data")
	tmplDir := envOr("TEMPLATE_DIR", "templates")
	staticDir := envOr("STATIC_DIR", "static")
	addr := envOr("ADDR", ":8080")

	s, err := store.Load(dataDir)
	if err != nil {
		log.Fatalf("failed to load fixture data: %v", err)
	}

	tmpl, err := template.ParseGlob(filepath.Join(tmplDir, "*.html"))
	if err != nil {
		log.Fatalf("failed to parse templates: %v", err)
	}

	a := &app{
		tmpl:         tmpl,
		dataStore:    s,
		surface:      quality.Build(s.Quality),
		policyReport: policy.Run(s.Decisions.RecentDecisions, s.Policy),
		reviewQueue:  review.NewQueue(s.Quality.DisagreementsSample),
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/", a.handleHome)
	mux.HandleFunc("/policy", a.handlePolicy)
	mux.HandleFunc("/review", a.handleReview)
	mux.HandleFunc("/review/", a.handleReviewAction)
	mux.Handle("/static/", http.StripPrefix("/static/", http.FileServer(http.Dir(staticDir))))

	log.Printf("sekats listening on %s (data=%s)", addr, dataDir)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatal(err)
	}
}

func (a *app) handleHome(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	a.renderPage(w, "page-home", "Quality Surface", struct {
		Surface quality.Surface
	}{Surface: a.surface})
}

func (a *app) handlePolicy(w http.ResponseWriter, r *http.Request) {
	a.renderPage(w, "page-policy", "Policy-as-ACs", struct {
		Report policy.Report
	}{Report: a.policyReport})
}

func (a *app) handleReview(w http.ResponseWriter, r *http.Request) {
	pending, accepted, rejected := a.reviewQueue.Counts()
	a.renderPage(w, "page-review", "Review Queue", struct {
		Items    []review.Item
		Pending  int
		Accepted int
		Rejected int
	}{
		Items:    a.reviewQueue.All(),
		Pending:  pending,
		Accepted: accepted,
		Rejected: rejected,
	})
}

// handleReviewAction handles POST /review/{id}/accept and
// POST /review/{id}/reject, returning the updated row partial for htmx to
// swap in place.
func (a *app) handleReviewAction(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.NotFound(w, r)
		return
	}
	parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
	if len(parts) != 3 || parts[0] != "review" {
		http.NotFound(w, r)
		return
	}
	id, err := strconv.ParseInt(parts[1], 10, 64)
	if err != nil {
		http.Error(w, "invalid decision id", http.StatusBadRequest)
		return
	}

	var verdict review.Verdict
	switch parts[2] {
	case "accept":
		verdict = review.VerdictAccepted
	case "reject":
		verdict = review.VerdictRejected
	default:
		http.NotFound(w, r)
		return
	}

	if !a.reviewQueue.SetVerdict(id, verdict) {
		http.NotFound(w, r)
		return
	}

	var item review.Item
	for _, it := range a.reviewQueue.All() {
		if it.DecisionID == id {
			item = it
			break
		}
	}
	pending, accepted, rejected := a.reviewQueue.Counts()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	err = a.tmpl.ExecuteTemplate(w, "review-action-response", struct {
		Item   review.Item
		Counts struct {
			Pending  int
			Accepted int
			Rejected int
		}
	}{
		Item: item,
		Counts: struct {
			Pending  int
			Accepted int
			Rejected int
		}{Pending: pending, Accepted: accepted, Rejected: rejected},
	})
	if err != nil {
		log.Printf("render review-action-response: %v", err)
	}
}

// renderPage executes the named page-content template into a buffer, then
// wraps that HTML in the shared layout. Rendering in two passes (rather
// than one template with a dynamic {{template}} name) avoids every page's
// "body" block colliding in the shared template.ParseGlob namespace.
func (a *app) renderPage(w http.ResponseWriter, pageTemplate, title string, pageData any) {
	var buf bytes.Buffer
	if err := a.tmpl.ExecuteTemplate(&buf, pageTemplate, pageData); err != nil {
		log.Printf("render %s: %v", pageTemplate, err)
		http.Error(w, "render error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	err := a.tmpl.ExecuteTemplate(w, "layout", struct {
		Title string
		Body  template.HTML
	}{Title: title, Body: template.HTML(buf.String())})
	if err != nil {
		log.Printf("render layout: %v", err)
		http.Error(w, "render error", http.StatusInternalServerError)
	}
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

// Package quality computes the display-ready numbers for the Quality
// Surface screen from the raw fixture stats.
package quality

import (
	"github.com/udingethe/sekats/internal/store"
)

// Surface is everything the "/" screen needs, pre-computed so the template
// stays dumb.
type Surface struct {
	PolicySuggestionsTotal    int
	PolicySuggestionsPromoted int
	PromotionRatePct          float64

	LLMReviewsTotal int
	LinkedReviews   int
	ErrorBuckets    []store.ErrorBucket
	CleanReviews    int
	ErrorReviews    int
	ErrorRatePct    float64

	AgreementAgree   int
	AgreementTotal   int
	AgreementRatePct float64
}

// Build derives a Surface from the raw QualityStats fixture.
func Build(s store.QualityStats) Surface {
	surf := Surface{
		PolicySuggestionsTotal:    s.PolicySuggestionsTotal,
		PolicySuggestionsPromoted: s.PolicySuggestionsPromoted,
		LLMReviewsTotal:           s.LLMReviewsTotal,
		LinkedReviews:             s.LinkedReviews,
		ErrorBuckets:              s.LLMReviewsByError,
		AgreementAgree:            s.AgreementRate.Agree,
		AgreementTotal:            s.AgreementRate.Total,
	}

	if surf.PolicySuggestionsTotal > 0 {
		surf.PromotionRatePct = pct(surf.PolicySuggestionsPromoted, surf.PolicySuggestionsTotal)
	}

	for _, b := range s.LLMReviewsByError {
		if b.Bucket == "clean" {
			surf.CleanReviews += b.Count
		} else {
			surf.ErrorReviews += b.Count
		}
	}
	if total := surf.CleanReviews + surf.ErrorReviews; total > 0 {
		surf.ErrorRatePct = pct(surf.ErrorReviews, total)
	}

	if surf.AgreementTotal > 0 {
		surf.AgreementRatePct = pct(surf.AgreementAgree, surf.AgreementTotal)
	}

	return surf
}

func pct(numerator, denominator int) float64 {
	if denominator == 0 {
		return 0
	}
	return float64(numerator) / float64(denominator) * 100
}

// Package store loads the frozen fixture data exported from the DevFun
// Arena poker agent's SQLite database. All data here is a snapshot, not a
// live connection — see docs/PLAN.md for why.
package store

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// Decision is one row from our_decisions, as produced by
// poker/tools/export_scenarios.py.
type Decision struct {
	Mode      string   `json:"mode"`
	Street    string   `json:"street"`
	HandCode  string   `json:"hand_code"`
	BoardJSON string   `json:"board_json"`
	Pot       float64  `json:"pot"`
	LegalJSON string   `json:"legal_json"`
	Action    string   `json:"action"`
	Amount    *float64 `json:"amount"`
	Source    string   `json:"source"`
	Accepted  int      `json:"accepted"`
	Error     *string  `json:"error"`
}

// PolicySuggestion is one row from policy_suggestions. created_at is stored
// as an epoch-ms integer in SQLite (see AGENTS.md's warning about manual
// epoch-ms math elsewhere in this codebase) — kept as int64 here rather
// than converted, since this app only counts/displays suggestions and
// never needs wall-clock arithmetic on them.
type PolicySuggestion struct {
	CreatedAt      int64   `json:"created_at"`
	Model          string  `json:"model"`
	Summary        string  `json:"summary"`
	Status         string  `json:"status"`
	Error          *string `json:"error"`
	SuggestionJSON string  `json:"suggestion_json"`
}

// DecisionsExport mirrors the top-level shape of decisions_export.json.
type DecisionsExport struct {
	RecentDecisions   []Decision         `json:"recent_decisions"`
	PolicySuggestions []PolicySuggestion `json:"policy_suggestions"`
}

// ErrorBucket counts llm_reviews rows grouped by error string ("clean" for
// no error).
type ErrorBucket struct {
	Bucket string `json:"bucket"`
	Count  int    `json:"c"`
}

// AgreementPair counts how often our_decisions.action lined up (or not)
// with the shadow-LLM's suggested action.
type AgreementPair struct {
	OurAction string `json:"our_action"`
	LLMAction string `json:"llm_action"`
	Count     int    `json:"c"`
}

// AgreementRate is the overall agree/total count across linked reviews.
type AgreementRate struct {
	Agree int `json:"agree"`
	Total int `json:"total"`
}

// PreflopActionCount counts preflop actions by hand code.
type PreflopActionCount struct {
	HandCode string `json:"hand_code"`
	Action   string `json:"action"`
	Count    int    `json:"c"`
}

// Disagreement is one real hand where the agent and the shadow-LLM review
// disagreed on the action.
type Disagreement struct {
	OurAction    string  `json:"our_action"`
	LLMAction    string  `json:"llm_action"`
	HandCode     string  `json:"hand_code"`
	Street       string  `json:"street"`
	Pot          float64 `json:"pot"`
	ResponseText string  `json:"response_text"`
	DecisionID   int64   `json:"decision_id"`
}

// QualityStats mirrors the top-level shape of quality_stats.json.
type QualityStats struct {
	PolicySuggestionsTotal    int                  `json:"policy_suggestions_total"`
	PolicySuggestionsPromoted int                  `json:"policy_suggestions_promoted"`
	LLMReviewsTotal           int                  `json:"llm_reviews_total"`
	LLMReviewsByError         []ErrorBucket        `json:"llm_reviews_by_error"`
	LinkedReviews             int                  `json:"linked_reviews"`
	AgreementBreakdown        []AgreementPair      `json:"agreement_breakdown"`
	AgreementRate             AgreementRate        `json:"agreement_rate"`
	PreflopActionDist         []PreflopActionCount `json:"preflop_action_dist"`
	DisagreementsSample       []Disagreement       `json:"disagreements_sample"`
}

// Policy mirrors the fields of poker-policy.json this app needs. Unknown
// fields are ignored via json.RawMessage passthrough where relevant, but for
// the AC engine we only need the preflop hand-list sections.
type Policy struct {
	Version int `json:"version"`
	Preflop struct {
		Premium                 []string `json:"premium"`
		Strong                  []string `json:"strong"`
		PlayableSuited          []string `json:"playableSuited"`
		PlayableOffsuitLate     []string `json:"playableOffsuitLate"`
		DominatedFoldCandidates []string `json:"dominatedFoldCandidates"`
		TrashExamples           []string `json:"trashExamples"`
	} `json:"preflop"`
}

// Store holds all loaded fixture data for the app's lifetime. It is
// read-only after Load — the review queue's mutable state lives separately
// in internal/review.
type Store struct {
	Decisions DecisionsExport
	Quality   QualityStats
	Policy    Policy
}

// Load reads all fixture JSON files from dataDir (typically "data/").
func Load(dataDir string) (*Store, error) {
	s := &Store{}

	if err := readJSON(filepath.Join(dataDir, "decisions_export.json"), &s.Decisions); err != nil {
		return nil, err
	}
	if err := readJSON(filepath.Join(dataDir, "quality_stats.json"), &s.Quality); err != nil {
		return nil, err
	}
	if err := readJSON(filepath.Join(dataDir, "poker-policy.json"), &s.Policy); err != nil {
		return nil, err
	}

	return s, nil
}

func readJSON(path string, v any) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return json.NewDecoder(f).Decode(v)
}

