:root {
  --bg: #0f1115;
  --panel: #171a21;
  --border: #2a2e38;
  --text: #e6e8ec;
  --muted: #8b90a0;
  --accent: #6ee7b7;
  --danger: #f87171;
  --warn: #fbbf24;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.topnav {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 32px;
  border-bottom: 1px solid var(--border);
}

.topnav .brand { font-weight: 700; margin-right: 16px; }
.topnav a { color: var(--muted); text-decoration: none; }
.topnav a:hover { color: var(--text); }

.content { padding: 32px; max-width: 1000px; margin: 0 auto; }

h1 { margin-bottom: 4px; }
.subtitle { color: var(--muted); margin-top: 0; margin-bottom: 24px; }

.callout {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
  margin-bottom: 24px;
}
.callout-broken { border-color: var(--danger); background: rgba(248, 113, 113, 0.08); }
.callout h2 { margin-top: 0; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin-bottom: 32px;
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 20px;
}
.card h3 { margin-top: 0; font-size: 14px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.05em; }
.big-number { font-size: 32px; font-weight: 700; margin: 4px 0; }
.big-number.violation-nonzero { color: var(--danger); }
.muted { color: var(--muted); font-size: 13px; }

.error-buckets { list-style: none; padding: 0; margin: 8px 0 0; font-size: 13px; }
.error-buckets li { display: flex; justify-content: space-between; padding: 2px 0; }
.bucket-count { color: var(--muted); }

.rule-list { list-style: none; padding: 0; }
.rule-list li { padding: 4px 0; }

.violations-table { width: 100%; border-collapse: collapse; margin-top: 12px; }
.violations-table th, .violations-table td { text-align: left; padding: 8px 12px; border-bottom: 1px solid var(--border); font-size: 13px; }

.empty-state { color: var(--accent); }

.review-item {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 12px;
  background: var(--panel);
}
.review-item.verdict-accepted { border-color: var(--accent); }
.review-item.verdict-rejected { border-color: var(--danger); }

.review-item-head { display: flex; gap: 12px; align-items: center; margin-bottom: 8px; font-size: 13px; color: var(--muted); }
.hand-code { font-weight: 700; color: var(--text); }
.verdict-badge {
  margin-left: auto;
  padding: 2px 8px;
  border-radius: 6px;
  background: var(--border);
  font-size: 11px;
  text-transform: uppercase;
}

.llm-rationale {
  background: #0b0d11;
  border-radius: 6px;
  padding: 10px;
  font-size: 12px;
  white-space: pre-wrap;
  color: var(--muted);
}

.review-item-actions { display: flex; gap: 8px; margin-top: 10px; }
.btn {
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
}
.btn-accept:hover { border-color: var(--accent); color: var(--accent); }
.btn-reject:hover { border-color: var(--danger); color: var(--danger); }

