</div>
{{end}}

{{define "review-counts-inner"}}
  <div class="card"><h3>Pending</h3><p class="big-number">{{.Pending}}</p></div>
  <div class="card"><h3>Accepted (agent right)</h3><p class="big-number">{{.Accepted}}</p></div>
  <div class="card"><h3>Rejected (LLM right)</h3><p class="big-number">{{.Rejected}}</p></div>
{{end}}

{{/* Response to an accept/reject POST: the updated row (swapped in place)
     plus an out-of-band swap of the summary counters, so the Pending/
     Accepted/Rejected totals never go stale relative to the row's own
     verdict badge — see the "counters stay stale" bug Kane caught. */}}
{{define "review-action-response"}}
{{template "review-row" .Item}}
<div id="review-counts" hx-swap-oob="true" class="grid" data-testid="review-counts">
  {{template "review-counts-inner" .Counts}}
</div>
{{end}}

