// Package review implements the human review queue: real hands where the
// agent's decision and the shadow-LLM review disagreed, with a human
// accept/reject verdict recorded against each one.
//
// State is persisted to data/verdicts.json so a restart preserves human
// adjudications. See docs/PLAN.md for the hackathon context.
package review

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sync"

	"github.com/udingethe/sekats/internal/store"
)

// Verdict is the human's call on one disagreement: accept the agent's
// action as correct, or reject it in favor of the shadow-LLM's suggestion.
type Verdict string

const (
	VerdictPending  Verdict = "pending"
	VerdictAccepted Verdict = "accepted" // human agrees with the agent
	VerdictRejected Verdict = "rejected" // human agrees with the shadow-LLM
)

// Item pairs a disagreement fixture with its current human verdict.
type Item struct {
	store.Disagreement
	Verdict Verdict
}

// Queue holds the review items and guards concurrent access from HTTP
// handlers with a mutex (this is a small single-process demo server, not a
// distributed system — a mutex is the right amount of complexity here).
// Verdicts are persisted to disk so a restart does not lose a human's calls.
type Queue struct {
	mu      sync.RWMutex
	items   []Item
	dataDir string // used to persist verdicts
}

// NewQueue seeds a queue from the disagreement fixtures, all starting
// pending, then restores any previously saved verdicts from dataDir.
func NewQueue(dataDir string, disagreements []store.Disagreement) *Queue {
	q := &Queue{
		items:   make([]Item, 0, len(disagreements)),
		dataDir: dataDir,
	}
	for _, d := range disagreements {
		q.items = append(q.items, Item{Disagreement: d, Verdict: VerdictPending})
	}
	q.load()
	return q
}

// load restores saved verdicts from data/verdicts.json if it exists.
func (q *Queue) load() {
	q.mu.Lock()
	defer q.mu.Unlock()
	path := filepath.Join(q.dataDir, "verdicts.json")
	f, err := os.Open(path)
	if err != nil {
		return // no saved state yet — fine
	}
	defer f.Close()
	var saved map[int64]Verdict
	if err := json.NewDecoder(f).Decode(&saved); err != nil {
		return
	}
	for i := range q.items {
		if v, ok := saved[q.items[i].DecisionID]; ok {
			q.items[i].Verdict = v
		}
	}
}

// persist writes the current verdict map to data/verdicts.json atomically.
func (q *Queue) persist() {
	if q.dataDir == "" {
		return
	}
	q.mu.RLock()
	saved := make(map[int64]Verdict, len(q.items))
	for _, it := range q.items {
		if it.Verdict != VerdictPending {
			saved[it.DecisionID] = it.Verdict
		}
	}
	q.mu.RUnlock()
	tmp := filepath.Join(q.dataDir, "verdicts.json.tmp")
	out := filepath.Join(q.dataDir, "verdicts.json")
	b, err := json.MarshalIndent(saved, "", "  ")
	if err != nil {
		return
	}
	if err := os.WriteFile(tmp, b, 0644); err != nil {
		return
	}
	os.Rename(tmp, out)
}

// All returns a snapshot of the current queue state.
func (q *Queue) All() []Item {
	q.mu.RLock()
	defer q.mu.RUnlock()
	out := make([]Item, len(q.items))
	copy(out, q.items)
	return out
}

// SetVerdict records a human decision for the item with the given
// decision ID. Returns false if no matching item was found. Persists
// the updated state to disk immediately.
func (q *Queue) SetVerdict(decisionID int64, v Verdict) bool {
	q.mu.Lock()
	defer q.mu.Unlock()
	for i := range q.items {
		if q.items[i].DecisionID == decisionID {
			q.items[i].Verdict = v
			q.persist()
			return true
		}
	}
	return false
}

// Counts returns how many items are in each verdict state.
func (q *Queue) Counts() (pending, accepted, rejected int) {
	q.mu.RLock()
	defer q.mu.RUnlock()
	for _, it := range q.items {
		switch it.Verdict {
		case VerdictPending:
			pending++
		case VerdictAccepted:
			accepted++
		case VerdictRejected:
			rejected++
		}
	}
	return
}

// Package trends prepares the data for the /trends screen: the suggestion
// timeline (with model attribution), the disagreement-action matrix, and the
// unused preflop action distribution. All numbers come from deterministic
// computation over the fixture data, never from an LLM.
package trends

import (
	"sort"
	"strings"
	"time"

	"github.com/udingethe/sekats/internal/store"
)

// TimelineEntry is one policy-suggestion row as shown on the trends screen.
type TimelineEntry struct {
	Timestamp string
	HumanTime string // formatted as "2026-07-20 14:12"
	Model     string
	Status    string
	Summary   string
}

// MatrixCell is one cell in the disagreement-action cross-tabulation.
type MatrixCell struct {
	OurAction  string
	LLMAction  string
	Count      int
	IsDisagree bool
}

// TrendData is everything the /trends page template needs.
type TrendData struct {
	Timeline       []TimelineEntry
	Matrix         []MatrixCell
	PreflopActions []store.PreflopActionCount
}

// Build derives a TrendData from the fixture store.
func Build(s store.Store) TrendData {
	td := TrendData{
		Timeline:       buildTimeline(s.Decisions.PolicySuggestions),
		Matrix:         buildMatrix(s.Quality.AgreementBreakdown),
		PreflopActions: s.Quality.PreflopActionDist,
	}
	sort.Slice(td.PreflopActions, func(i, j int) bool {
		return td.PreflopActions[i].Count > td.PreflopActions[j].Count
	})
	// Drop the top 5 used actions so we surface only what's missing.
	if len(td.PreflopActions) > 5 {
		td.PreflopActions = td.PreflopActions[5:]
	}
	return td
}

func buildTimeline(suggestions []store.PolicySuggestion) []TimelineEntry {
	entries := make([]TimelineEntry, 0, len(suggestions))
	for _, s := range suggestions {
		t := epochMsToTime(s.CreatedAt)
		entries = append(entries, TimelineEntry{
			Timestamp: t.Format(time.RFC3339Nano),
			HumanTime: t.Format("2006-01-02 15:04"),
			Model:     s.Model,
			Status:    s.Status,
			Summary:   s.Summary,
		})
	}
	// Reverse so newest-first.
	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
		entries[i], entries[j] = entries[j], entries[i]
	}
	return entries
}

func epochMsToTime(ms int64) time.Time {
	if ms > 1e12 {
		return time.Unix(0, ms*int64(time.Millisecond))
	}
	return time.Unix(ms, 0)
}

func buildMatrix(breakdown []store.AgreementPair) []MatrixCell {
	cells := make([]MatrixCell, 0, len(breakdown))
	for _, b := range breakdown {
		cells = append(cells, MatrixCell{
			OurAction:  b.OurAction,
			LLMAction:  b.LLMAction,
			Count:      b.Count,
			IsDisagree: b.OurAction != b.LLMAction,
		})
	}
	// Put disagreements first (the interesting ones), then agreements.
	sort.SliceStable(cells, func(i, j int) bool {
		if cells[i].IsDisagree != cells[j].IsDisagree {
			return cells[i].IsDisagree
		}
		return cells[i].Count > cells[j].Count
	})
	return cells
}

// shortModel strips the provider prefix so "openrouter:tencent/hy3:free"
// becomes "tencent/hy3". Useful for table headers.
func ShortModel(full string) string {
	parts := strings.SplitN(full, ":", 2)
	if len(parts) == 2 {
		return parts[1]
	}
	return full
}

