// Shareable verdict report: a markdown document joining every recorded
// human verdict with the fixture row it adjudicated, so a reviewer outside
// the console (or a future self) can see exactly what was decided and why,
// without running the app.

package verdicts

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/udingethe/sekats/internal/store"
)

// JoinError flags one verdict whose decision_id had no matching
// disagreement fixture row — data drift, not a crash.
type JoinError struct {
	DecisionID int64
	Verdict    string
}

// BuildReport joins the recorded verdicts against the disagreement fixture
// rows. Verdicts that reference a decision ID absent from the fixtures are
// surfaced in Missing rather than silently dropped.
func BuildReport(queued []store.Disagreement, entries []Entry) (string, []JoinError) {
	byID := make(map[int64]store.Disagreement, len(queued))
	for _, d := range queued {
		byID[d.DecisionID] = d
	}

	accepted, rejected := 0, 0
	type row struct {
		e       Entry
		d       store.Disagreement
		missing bool
	}
	rows := make([]row, 0, len(entries))
	var missing []JoinError

	for _, e := range entries {
		d, ok := byID[e.DecisionID]
		switch {
		case ok && e.Verdict == "accepted":
			accepted++
		case ok && e.Verdict == "rejected":
			rejected++
		}
		if !ok {
			missing = append(missing, JoinError{DecisionID: e.DecisionID, Verdict: e.Verdict})
		}
		rows = append(rows, row{e: e, d: d, missing: !ok})
	}

	sort.Slice(rows, func(i, j int) bool { return rows[i].e.DecisionID < rows[j].e.DecisionID })

	var b strings.Builder
	b.WriteString("# Sekats — Human Verdict Report\n\n")
	fmt.Fprintf(&b, "Generated: %s\n\n", time.Now().UTC().Format(time.RFC1123))
	fmt.Fprintf(&b, "These are the calls a human made on the review queue: for each hand where the agent's action and the shadow-LLM review disagreed, which side did the human side with.\n\n")

	total := len(rows)
	fmt.Fprintf(&b, "| Agent (accepted) | Shadow-LLM (rejected) | Total |\n|---|---|---|\n| %d | %d | %d |\n\n", accepted, rejected, total)

	if total > 0 {
		b.WriteString("## Adjudications\n\n")
		for _, r := range rows {
			if r.missing {
				fmt.Fprintf(&b, "- decision_id %d: verdict %q, but no matching fixture row (data drift — export the fixtures again).\n", r.e.DecisionID, r.e.Verdict)
				continue
			}
			who := "the agent was right"
			if r.e.Verdict == "rejected" {
				who = "the shadow-LLM was right"
			}
			fmt.Fprintf(&b, "### %s on %s (%s) — %s\n\n", r.e.Verdict, r.d.HandCode, r.d.Street, who)
			fmt.Fprintf(&b, "- Agent action: `%s`  |  Shadow-LLM action: `%s`  |  Pot: %.2f\n", r.d.OurAction, r.d.LLMAction, r.d.Pot)
			fmt.Fprintf(&b, "- Recorded: %s\n\n", r.e.RecordedAt.Format("2006-01-02 15:04 UTC"))
			if rt := strings.TrimSpace(r.d.ResponseText); rt != "" {
				b.WriteString("Shadow-LLM response (trimmed):\n\n```\n")
				b.WriteString(rt)
				b.WriteString("\n```\n\n")
			}
		}
	}

	if len(missing) > 0 {
		b.WriteString("## Unmatched verdicts\n\n")
		for _, m := range missing {
			fmt.Fprintf(&b, "- decision_id %d (%s): not present in the frozen fixture export\n", m.DecisionID, m.Verdict)
		}
		b.WriteString("\n")
	}

	if total == 0 {
		b.WriteString("_No verdicts recorded yet. Adjudicate hands on the Review Queue screen; this report regenerates from the saved verdict file._\n")
	}

	return b.String(), missing
}
// Package verdicts persists the review queue's human verdicts to a JSON
// file on disk. Verdicts were in-memory only before; now the accept/reject
// calls a human makes in the queue survive a restart and feed the
// /verdicts report, so the queue's output is a durable artifact.
package verdicts

import (
	"encoding/json"
	"os"
	"sort"
	"strconv"
	"sync"
	"time"
)

// Entry is one recorded human verdict.
type Entry struct {
	DecisionID int64
	Verdict    string // "accepted" (human agrees with the agent) or "rejected" (human agrees with the shadow-LLM)
	RecordedAt time.Time
}

// Store guards a map of decisionID -> Entry with a mutex and flushes the
// current state to a JSON file after every write.
type Store struct {
	mu       sync.Mutex
	path     string
	verdicts map[int64]Entry
}

// NewStore returns a store writing to path. Pass an empty path to disable
// persistence (verdicts stay in memory only).
func NewStore(path string) *Store {
	return &Store{path: path, verdicts: make(map[int64]Entry)}
}

// Load reads previously-saved verdicts from disk, if any. A missing file is
// not an error — the queue simply starts blank.
func (s *Store) Load() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.path == "" {
		return nil
	}
	f, err := os.Open(s.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	defer f.Close()
	var saved map[string]Entry // JSON object keys are strings.
	if err := json.NewDecoder(f).Decode(&saved); err != nil {
		return err
	}
	for k, e := range saved {
		id, err := strconv.ParseInt(k, 10, 64)
		if err != nil {
			continue
		}
		s.verdicts[id] = e
	}
	return nil
}

// Record saves a verdict for the given decision ID and flushes to disk.
func (s *Store) Record(decisionID int64, verdict string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.verdicts[decisionID] = Entry{
		DecisionID: decisionID,
		Verdict:    verdict,
		RecordedAt: time.Now().UTC(),
	}
	return s.flushLocked()
}

// flushLocked writes the current map to disk. Caller holds s.mu.
func (s *Store) flushLocked() error {
	if s.path == "" {
		return nil
	}
	out := make(map[string]Entry, len(s.verdicts))
	for id, e := range s.verdicts {
		out[strconv.FormatInt(id, 10)] = e
	}
	b, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(s.path, b, 0o644)
}

// All returns a snapshot of every recorded verdict, sorted by decision ID.
func (s *Store) All() []Entry {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]Entry, 0, len(s.verdicts))
	for _, e := range s.verdicts {
		out = append(out, e)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].DecisionID < out[j].DecisionID })
	return out
}

// Lookup returns the verdict for one decision ID, if recorded.
func (s *Store) Lookup(decisionID int64) (Entry, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.verdicts[decisionID]
	return e, ok
}

// Package review implements the human review queue: real hands where the
// agent's decision and the shadow-LLM review disagreed, with a human
// accept/reject verdict recorded against each one.
//
// State is in-memory for the hackathon demo — see docs/PLAN.md. A restart
// resets verdicts, which is fine for a judged demo but called out here so a
// future contributor doesn't assume durability.
package review

import (
	"sync"

	"github.com/udingethe/sekats/internal/store"
)

// Verdict is the human's call on one disagreement: accept the agent's
// action as correct, or reject it in favor of the shadow-LLM's suggestion.
type Verdict string

const (
	VerdictPending  Verdict = "pending"
	VerdictAccepted Verdict = "accepted" // human agrees with the agent
	VerdictRejected Verdict = "rejected" // human agrees with the shadow-LLM
)

// Item pairs a disagreement fixture with its current human verdict.
type Item struct {
	store.Disagreement
	Verdict Verdict
}

// Queue holds the review items and guards concurrent access from HTTP
// handlers with a mutex (this is a small single-process demo server, not a
// distributed system — a mutex is the right amount of complexity here).
type Queue struct {
	mu    sync.RWMutex
	items []Item
}

// NewQueue seeds a queue from the disagreement fixtures, all starting
// pending.
func NewQueue(disagreements []store.Disagreement) *Queue {
	q := &Queue{items: make([]Item, 0, len(disagreements))}
	for _, d := range disagreements {
		q.items = append(q.items, Item{Disagreement: d, Verdict: VerdictPending})
	}
	return q
}

// All returns a snapshot of the current queue state.
func (q *Queue) All() []Item {
	q.mu.RLock()
	defer q.mu.RUnlock()
	out := make([]Item, len(q.items))
	copy(out, q.items)
	return out
}

// SetVerdict records a human decision for the item with the given
// decision ID. Returns false if no matching item was found.
func (q *Queue) SetVerdict(decisionID int64, v Verdict) bool {
	q.mu.Lock()
	defer q.mu.Unlock()
	for i := range q.items {
		if q.items[i].DecisionID == decisionID {
			q.items[i].Verdict = v
			return true
		}
	}
	return false
}

// Counts returns how many items are in each verdict state.
func (q *Queue) Counts() (pending, accepted, rejected int) {
	q.mu.RLock()
	defer q.mu.RUnlock()
	for _, it := range q.items {
		switch it.Verdict {
		case VerdictPending:
			pending++
		case VerdictAccepted:
			accepted++
		case VerdictRejected:
			rejected++
		}
	}
	return
}

